function collect({ contacts, pagination, previousState }) {
  const s = previousState ?? { records: [], page: 0, totalPages: null, totalCount: null };
  if (!Array.isArray(contacts) || !Array.isArray(s.records) || !pagination)
    throw Error("Invalid contact page");
  const { currentPage, totalPages, totalCount } = pagination;
  if (
    !Number.isInteger(currentPage) ||
    !Number.isInteger(totalPages) ||
    !Number.isInteger(totalCount) ||
    currentPage !== s.page + 1 ||
    totalPages < 0 ||
    totalCount < 0 ||
    (s.totalPages !== null && (s.totalPages !== totalPages || s.totalCount !== totalCount)) ||
    (totalPages === 0 && (currentPage !== 1 || contacts.length !== 0 || totalCount !== 0)) ||
    (totalPages > 0 && currentPage > totalPages)
  )
    throw Error("Inconsistent pagination");
  const records = [...s.records, ...contacts];
  if (records.length > totalCount || (!contacts.length && currentPage < totalPages))
    throw Error("Incomplete contact page");
  const more = currentPage < totalPages;
  if (!more && records.length !== totalCount) throw Error("Contact total changed during reading");
  return {
    state: { records, page: currentPage, totalPages, totalCount },
    more,
    nextPage: currentPage + 1,
  };
}

function plan({ state, campaign, targetCampaignId }) {
  if (
    typeof targetCampaignId !== "string" ||
    !targetCampaignId.trim() ||
    targetCampaignId === "YOUR_CAMPAIGN_ID" ||
    campaign?.campaignId !== targetCampaignId ||
    typeof campaign.name !== "string" ||
    !campaign.name
  )
    throw Error("Configure a valid target campaign");
  if (!Array.isArray(state?.records)) throw Error("Invalid contact list");
  const ids = [],
    seen = new Set();
  for (const c of state.records) {
    if (
      typeof c?.contactId !== "string" ||
      !c.contactId ||
      !c.campaign ||
      typeof c.campaign.name !== "string" ||
      typeof c.campaign.campaignId !== "string"
    )
      throw Error("Contact lacks campaign identity");
    if (seen.has(c.contactId)) throw Error("Duplicate contact in paginated list");
    seen.add(c.contactId);
    if (c.campaign.name !== campaign.name) ids.push(c.contactId);
  }
  return { ids, targetCampaignId };
}

let state = null,
  more = false;
for (const x of $input.all()) {
  const h = x.json.headers ?? {},
    v = (k) => {
      const t = h[k];
      if (t == null || String(t).trim() === "") throw Error("Missing pagination header");
      return Number(t);
    };
  const result = collect({
    contacts: x.json.body,
    pagination: {
      currentPage: v("currentpage"),
      totalPages: v("totalpages"),
      totalCount: v("totalcount"),
    },
    previousState: state,
  });
  state = result.state;
  more = result.more;
}
if (more) throw Error("Contact page limit reached");
const campaign = $("Read destination list").first().json;
const result = plan({ state, campaign, targetCampaignId: campaign.campaignId });
return result.ids.map((contactId) => ({
  json: { contactId, campaignId: result.targetCampaignId },
}));
